  /// The poem that owns [page] (last poem whose page is <= [page]).
  static Poem poemForPage(int page) {
    var active = poems.first;
    for (final p in poems) {
      if (page >= p.page) active = p;
    }
    return active;
  }

  /// First PDF page of the poem after [poem], or [totalPages] + 1.
  static int nextPoemStart(Poem poem) {
    final idx = poems.indexWhere((p) => p.id == poem.id);
    if (idx >= 0 && idx < poems.length - 1) return poems[idx + 1].page;
    return totalPages + 1;
  }

  static Poem? poemById(int id) {
    for (final p in poems) {
      if (p.id == id) return p;
    }
    return null;
  }
